// ---- helpers do contrato ----
const DIAS = ['SEGUNDA', 'TERCA', 'QUARTA', 'QUINTA', 'SEXTA'];            // RN04
const PERIODOS = ['MATUTINO', 'VESPERTINO', 'NOTURNO'];                   // RN03
const HHMM = /^([01]\d|2[0-3]):[0-5]\d$/;                                 // "HH:MM"
const body = () => insomnia.response.json();
function camelCase(obj, caminho = '') {                                   // 2.5: camelCase, sem snake_case
  if (Array.isArray(obj)) return obj.forEach((x, i) => camelCase(x, `${caminho}[${i}]`));
  if (obj && typeof obj === 'object') for (const k of Object.keys(obj)) {
    insomnia.expect(k, `campo ${caminho}.${k}`).to.not.include('_');
    camelCase(obj[k], `${caminho}.${k}`);
  }
}
function erroPadrao(status) {                                              // 2.6: { erro, codigo }
  insomnia.test(`status ${status}`, () => insomnia.expect(insomnia.response.code).to.eql(status));
  insomnia.test('erro no formato { erro, codigo }', () => {
    const b = body();
    insomnia.expect(b.erro, 'erro').to.be.a('string').and.not.empty;
    insomnia.expect(b.codigo, 'codigo').to.be.a('string').and.not.empty;
  });
}
function ok200() {
  insomnia.test('status 200', () => insomnia.expect(insomnia.response.code).to.eql(200));
  insomnia.test('resposta em JSON', () =>
    insomnia.expect(insomnia.response.headers.get('content-type')).to.include('application/json'));
}
// ------------------------------
ok200();
insomnia.test('banco ok', () => insomnia.expect(body().banco).to.eql('ok'));

